import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  ChevronLeft, ChevronRight, Bed, Maximize2, MapPin,
  Clock, Building, Sparkles, X, CheckCircle2, ArrowRight, Image as ImageIcon
} from 'lucide-react';
import { getActiveAds, trackAdClick } from '../services/api';
import styles from './AdCarousel.module.css';

const AUTO_SWIPE_INTERVAL = 5500; // 5.5 seconds per ad

const FALLBACK_ADS = [
  {
    _id: 'default-ad-1',
    title: 'Luxury Apartments in Whitefield',
    image: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1600&auto=format&fit=crop&q=85',
    bedroom: '3 BHK',
    area: '1,850 Sq.ft',
    locality: 'Whitefield',
    city: 'Bengaluru',
    price: '₹1.25 Cr',
    priceNote: 'Onwards',
    possession: 'Ready to Move',
    buildingType: 'Residential',
    propertyType: 'Apartment',
    description: 'Experience contemporary luxury living in the heart of Whitefield. Spacious 3 BHK residences featuring world-class amenities, private balconies, and landscaped podium gardens.',
    amenities: ['Swimming Pool', 'Gym & Fitness', 'Clubhouse', 'Children Play Area', '24/7 Security', 'Power Backup'],
  },
  {
    _id: 'default-ad-2',
    title: 'Signature Villa in Indiranagar',
    image: 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1600&auto=format&fit=crop&q=85',
    bedroom: '4 BHK',
    area: '3,200 Sq.ft',
    locality: 'Indiranagar',
    city: 'Bengaluru',
    price: '₹3.80 Cr',
    priceNote: 'Onwards',
    possession: 'Ready to Move',
    buildingType: 'Residential',
    propertyType: 'Villa',
    description: 'Exclusive gated community luxury villas with personal plunge pool, Italian marble flooring, and smart home automation in prime Indiranagar.',
    amenities: ['Private Pool', 'Home Automation', 'Private Lawn', 'Clubhouse', '24/7 Security', 'Covered Parking'],
  },
  {
    _id: 'default-ad-3',
    title: 'Modern Sky Penthouse in Koramangala',
    image: 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1600&auto=format&fit=crop&q=85',
    bedroom: '3 BHK',
    area: '2,400 Sq.ft',
    locality: 'Koramangala',
    city: 'Bengaluru',
    price: '₹2.10 Cr',
    priceNote: 'Onwards',
    possession: 'Under Construction',
    buildingType: 'Residential',
    propertyType: 'Penthouse',
    description: 'Sky-high luxury penthouse with panoramic city skyline views, private terrace garden, and double-height living room ceilings.',
    amenities: ['Sky Deck', 'Infinity Pool', 'Terrace Garden', 'Concierge Service', 'Gym & Spa', 'Valet Parking'],
  },
  {
    _id: 'default-ad-4',
    title: 'Grade-A Commercial Park in Cyber City',
    image: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1600&auto=format&fit=crop&q=85',
    bedroom: 'Commercial',
    area: '5,500 Sq.ft',
    locality: 'Cyber City',
    city: 'Hyderabad',
    price: '₹7.50 Cr',
    priceNote: 'Expected Yield 9.2%',
    possession: 'Immediate Possession',
    buildingType: 'Commercial',
    propertyType: 'Office Space',
    description: 'Pre-leased institutional-grade corporate office floor leased to MNC tenants with 9-year long lock-in and high annual rental appreciation.',
    amenities: ['High Speed Elevators', 'Central AC', 'Triple Height Lobby', 'Food Court', 'Multi-level Parking', '100% DG Backup'],
  },
];

export default function AdCarousel({ onEnquire }) {
  const navigate = useNavigate();
  const [ads, setAds] = useState(FALLBACK_ADS);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [selectedAd, setSelectedAd] = useState(null);

  // Fetch active ads from website backend
  useEffect(() => {
    let active = true;
    getActiveAds()
      .then(({ data }) => {
        if (!active) return;
        if (data && data.results && data.results.length > 0) {
          const formatted = data.results.map(ad => {
            const p = ad.property || {};
            return {
              _id: ad._id,
              title: ad.title || p.title || 'Featured Property',
              image: ad.image || p.image || FALLBACK_ADS[0].image,
              bedroom: p.bedroom || '3 BHK',
              area: p.area || p.plotSize || '1,800 Sq.ft',
              locality: p.locality || 'Prime Location',
              city: p.city || 'Bengaluru',
              price: p.price || 'Price on Request',
              priceNote: p.priceNote || 'Onwards',
              possession: p.possession || 'Ready to Move',
              buildingType: p.buildingType || 'Residential',
              propertyType: p.propertyType || 'Apartment',
              description: p.description || 'Exclusive premium property listing verified by ProBridge experts.',
              amenities: p.amenities && p.amenities.length > 0 ? p.amenities : ['Clubhouse', '24/7 Security', 'Covered Parking', 'Power Backup'],
              propertyId: p._id || p.id,
            };
          });
          setAds(formatted);
        }
      })
      .catch(() => {
        // Keeps FALLBACK_ADS
      });

    return () => { active = false; };
  }, []);

  // Automatic swipe one by one
  useEffect(() => {
    if (ads.length <= 1 || isPaused || selectedAd) return;

    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % ads.length);
    }, AUTO_SWIPE_INTERVAL);

    return () => clearInterval(timer);
  }, [ads.length, isPaused, selectedAd]);

  const handlePrev = useCallback((e) => {
    e?.stopPropagation();
    setCurrentIndex((prev) => (prev === 0 ? ads.length - 1 : prev - 1));
  }, [ads.length]);

  const handleNext = useCallback((e) => {
    e?.stopPropagation();
    setCurrentIndex((prev) => (prev + 1) % ads.length);
  }, [ads.length]);

  const handleOpenAd = useCallback((ad) => {
    setSelectedAd(ad);
    if (ad._id && !ad._id.startsWith('default-')) {
      trackAdClick(ad._id).catch(() => {});
    }
  }, []);

  const handleCloseModal = useCallback(() => {
    setSelectedAd(null);
  }, []);

  const handleModalCta = useCallback((ad) => {
    setSelectedAd(null);
    if (ad.propertyId) {
      navigate(`/search?q=${encodeURIComponent(ad.locality || ad.city || ad.title)}`);
    } else if (onEnquire) {
      onEnquire({
        title: ad.title,
        price: ad.price,
        location: `${ad.locality}, ${ad.city}`,
        image: ad.image,
      });
    } else {
      navigate(`/search?city=${encodeURIComponent(ad.city || '')}`);
    }
  }, [navigate, onEnquire]);

  if (!ads || ads.length === 0) return null;

  return (
    <div
      className={styles.carouselContainer}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      {/* ── Slide Viewport ── */}
      <div className={styles.sliderViewport}>
        <div
          className={styles.sliderTrack}
          style={{ transform: `translateX(-${currentIndex * 100}%)` }}
        >
          {ads.map((ad, idx) => (
            <div
              key={ad._id || idx}
              className={styles.slideCard}
              onClick={() => handleOpenAd(ad)}
            >
              {/* Background Image */}
              <img
                src={ad.image}
                alt={ad.title}
                className={styles.slideImg}
                loading={idx === 0 ? 'eager' : 'lazy'}
              />

              {/* Multi-layer luxury dark gradient */}
              <div className={styles.slideGradient} />

              {/* Top Controls Bar */}
              <div className={styles.topBar}>
                {/* Sponsored Pill Badge */}
                <div className={styles.sponsoredBadge}>
                  <Sparkles size={13} className={styles.sparkleIcon} />
                  <span>SPONSORED</span>
                </div>

                {/* Counter & Action */}
                <div className={styles.counterBadge}>
                  <ImageIcon size={13} />
                  <span>{idx + 1} / {ads.length}</span>
                </div>
              </div>

              {/* Bottom Content Area */}
              <div className={styles.bottomContent}>
                <div className={styles.infoCol}>
                  <h3 className={styles.adTitle}>{ad.title}</h3>

                  {/* Specs Row */}
                  <div className={styles.specsRow}>
                    {ad.bedroom && (
                      <span className={styles.specChip}>
                        <Bed size={14} />
                        <span>{ad.bedroom}</span>
                      </span>
                    )}
                    {ad.area && (
                      <span className={styles.specChip}>
                        <Maximize2 size={13} />
                        <span>{ad.area}</span>
                      </span>
                    )}
                    {(ad.locality || ad.city) && (
                      <span className={styles.specChip}>
                        <MapPin size={13} />
                        <span>{ad.locality}{ad.city ? `, ${ad.city}` : ''}</span>
                      </span>
                    )}
                    {ad.possession && (
                      <span className={styles.specChip}>
                        <Clock size={13} />
                        <span>{ad.possession}</span>
                      </span>
                    )}
                  </div>
                </div>

                {/* Price & Action Button */}
                <div className={styles.actionCol}>
                  <div className={styles.priceBlock}>
                    <span className={styles.priceMain}>{ad.price}</span>
                    {ad.priceNote && <span className={styles.priceSub}>{ad.priceNote}</span>}
                  </div>

                  <button
                    className={styles.viewDetailsBtn}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleOpenAd(ad);
                    }}
                  >
                    <span>View Details</span>
                    <ArrowRight size={15} />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* ── Prev / Next Navigation Arrows ── */}
        <button
          className={`${styles.navArrow} ${styles.navArrowPrev}`}
          onClick={handlePrev}
          aria-label="Previous ad"
        >
          <ChevronLeft size={22} />
        </button>
        <button
          className={`${styles.navArrow} ${styles.navArrowNext}`}
          onClick={handleNext}
          aria-label="Next ad"
        >
          <ChevronRight size={22} />
        </button>
      </div>

      {/* ── Dot Indicators ── */}
      <div className={styles.dotsRow}>
        {ads.map((_, i) => (
          <button
            key={i}
            className={`${styles.dot} ${i === currentIndex ? styles.dotActive : ''}`}
            onClick={() => setCurrentIndex(i)}
            aria-label={`Go to ad ${i + 1}`}
          />
        ))}
      </div>

      {/* ── Full Details Popup Modal (Matching the App) ── */}
      {selectedAd && (
        <div className={styles.modalOverlay} onClick={handleCloseModal}>
          <div className={styles.modalCard} onClick={(e) => e.stopPropagation()}>
            {/* Modal Banner Header */}
            <div className={styles.modalImageWrap}>
              <img src={selectedAd.image} alt={selectedAd.title} className={styles.modalImage} />
              <div className={styles.modalGradient} />

              <div className={styles.modalSponsoredBadge}>
                <Sparkles size={12} />
                <span>SPONSORED PROJECT</span>
              </div>

              <button className={styles.modalCloseBtn} onClick={handleCloseModal}>
                <X size={18} />
              </button>

              <div className={styles.modalPriceTag}>
                <span className={styles.modalPriceVal}>{selectedAd.price}</span>
                {selectedAd.priceNote && <span className={styles.modalPriceNote}>{selectedAd.priceNote}</span>}
              </div>
            </div>

            {/* Modal Scrollable Body */}
            <div className={styles.modalBody}>
              <h3 className={styles.modalTitle}>{selectedAd.title}</h3>

              <div className={styles.modalLocationRow}>
                <MapPin size={16} className={styles.modalPinIcon} />
                <span>{selectedAd.locality}, {selectedAd.city}</span>
              </div>

              {/* 4-Box Specs Grid */}
              <div className={styles.modalSpecsGrid}>
                <div className={styles.modalSpecBox}>
                  <Bed size={20} className={styles.specBoxIcon} />
                  <div>
                    <span className={styles.specBoxLabel}>Configuration</span>
                    <strong className={styles.specBoxVal}>{selectedAd.bedroom}</strong>
                  </div>
                </div>

                <div className={styles.modalSpecBox}>
                  <Maximize2 size={19} className={styles.specBoxIcon} />
                  <div>
                    <span className={styles.specBoxLabel}>Super Area</span>
                    <strong className={styles.specBoxVal}>{selectedAd.area}</strong>
                  </div>
                </div>

                <div className={styles.modalSpecBox}>
                  <Clock size={19} className={styles.specBoxIcon} />
                  <div>
                    <span className={styles.specBoxLabel}>Possession</span>
                    <strong className={styles.specBoxVal}>{selectedAd.possession}</strong>
                  </div>
                </div>

                <div className={styles.modalSpecBox}>
                  <Building size={19} className={styles.specBoxIcon} />
                  <div>
                    <span className={styles.specBoxLabel}>Property Type</span>
                    <strong className={styles.specBoxVal}>{selectedAd.propertyType || selectedAd.buildingType}</strong>
                  </div>
                </div>
              </div>

              {/* Description */}
              <div className={styles.modalSection}>
                <h4 className={styles.modalSubheading}>About this Development</h4>
                <p className={styles.modalDesc}>{selectedAd.description}</p>
              </div>

              {/* Amenities */}
              {selectedAd.amenities && selectedAd.amenities.length > 0 && (
                <div className={styles.modalSection}>
                  <h4 className={styles.modalSubheading}>Project Highlights &amp; Amenities</h4>
                  <div className={styles.amenitiesWrap}>
                    {selectedAd.amenities.map((item, i) => (
                      <span key={i} className={styles.amenityPill}>
                        <CheckCircle2 size={14} className={styles.checkIcon} />
                        <span>{item}</span>
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Modal Bottom CTA */}
            <div className={styles.modalFooter}>
              <button
                className={styles.modalCtaBtn}
                onClick={() => handleModalCta(selectedAd)}
              >
                <span>Connect With Builder &bull; Enquire Now</span>
                <ArrowRight size={17} />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
